import{_ as o,l,o as e,c as n,v as t,p as s,x as r,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"曲线掩模数据量","description":"","frontmatter":{"title":"曲线掩模数据量","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/curvilinear-data-volume.md","filePath":"litho/curvilinear-data-volume.md","lastUpdated":1789023840000}'),E={name:"litho/curvilinear-data-volume.md"};function c(A,a,u,B,m,_){const i=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="曲线掩模数据量" tabindex="-1">曲线掩模数据量 <a class="header-anchor" href="#曲线掩模数据量" aria-label="Permalink to &quot;曲线掩模数据量&quot;">​</a></h1><div class="epigraph"><p>ILT 的等值线一旦折成微矩形，文件与炮数一起爆炸；曲线格式把复杂度从「边数」改写为「控制点与栅格」。</p><footer>—— 对照曲线掩模、OASIS 与多束数据路径的公开可制造性讨论</footer></div><p><a href="/litho/mpc">上一课</a>把掩模工艺偏置收进数据链。缺口是 ILT 输出不是稀疏曼哈顿：全芯片曲边会让 GDS 边数、MDP 墙钟和检验比对同时爆。本课钉曲线数据量。写入时间怎么从数据变成小时，留给[下一课](/litho/mask-write-time）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/litho/curvilinear-mrc">曲线 MRC</a> 已经声明：可写曲线要有曲率与颈规则。本课补的是<strong>体积</strong>：同样一层，曼哈顿 OPC 可能几十 GB 量级的中间文件；曲线若用微矩形逼近，可以再涨一到两个数量级，网络、磁盘、校验器与 fracturing 先于写束成为 TAPOUT 墙。OASIS 重复记录救得了 SRAM 阵列，救不了每条助条都独特的 ILT 噪声边。</p><p>缺口是数据路径容量，不是再优化一次水平集。把「多束已量产」写成「文件大小无所谓」，会漏掉：检验 die-to-database 仍要展开几何；MPC/PEC 仍要卷积密度图。</p><h3 id="三种计量不要混" tabindex="-1">三种计量不要混 <a class="header-anchor" href="#三种计量不要混" aria-label="Permalink to &quot;三种计量不要混&quot;">​</a></h3><p>边数（多边形复杂度）、炮数（VSB）、像素数（多束栅格）是三张账。曲线的光学收益来自通带内的光滑边；数据灾难来自用错误基去存这条边。原生曲边或紧凑折线 + 多束栅格，才可能让「光学复杂度」与「存储复杂度」脱钩。</p><p><span class="marginnote">报 ILT 窗口时同时报全芯片输出体积与 MDP 墙钟。只展示热区 clip 的曲边，不能外推 TAPOUT 日历。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程选项：限制 ILT 为热区补丁（其余曼哈顿）以封顶数据量；全芯片曲线则必须走曲线感知的 OASIS、简化（抽控制点）在 MRC 之后、以及写模侧直接栅格化以免二次微矩形。抽点过度会制造新颈，与曲线 MRC 冲突——简化是优化问题，不是压缩软件。</p><p>与 <a href="/litho/computational-litho-gpu">GPU 计算光刻</a> 的分工：GPU 缩短反演；数据量是反演<strong>之后</strong>的物流。两者都要进节点周期时间。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>透镜通带是低通：描述一条光学上有效的边，理论上只需要截止频率对应的采样。微矩形用远高于通带的阶梯去存同一条边，信息论上浪费，写模与检验却按浪费后的复杂度付钱。多束位图的采样由束距决定，这才是与光学截止匹配或故意过采样的那张栅格。</p>',14)),(e(),s(p,null,{default:r(()=>[h(i,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ILT%5B%22ILT%20%E7%AD%89%E5%80%BC%E7%BA%BF%22%5D%20--%3E%20BAD%5B%22%E5%BE%AE%E7%9F%A9%E5%BD%A2%E9%80%BC%E8%BF%91%22%5D%0A%20%20BAD%20--%3E%20EXP%5B%22%E6%96%87%E4%BB%B6%20%2F%20%E7%82%AE%E6%95%B0%E7%88%86%E7%82%B8%22%5D%0A%20%20ILT%20--%3E%20CRV%5B%22%E6%9B%B2%E8%BE%B9%20OASIS%20%2B%20%E6%8A%BD%E7%82%B9%22%5D%0A%20%20CRV%20--%3E%20GRID%5B%22%E5%A4%9A%E6%9D%9F%E6%A0%85%E6%A0%BC%22%5D%0A%20%20GRID%20--%3E%20VOL%5B%22%E4%BD%93%E7%A7%AF%20~%20%E9%9D%A2%E7%A7%AF%20%C3%97%20%E5%88%86%E8%BE%A8%E7%8E%87%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>数据格式不增加光子。它只决定曲线层能不能进产线日历。知识产权比对（多边形等价）在曲边上更难，合同要另写容差。不要编造某层「一定 10× 压缩」——压缩比随重复性与抽点策略变。</p><p>后课默认：曲线层的复杂度按面积栅格估，不再默认随 jog 数线性涨；下一课把这张估计变成写入小时。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>曲线数据量爆炸来自错误的微矩形基，不是来自光学信息本身。</li><li>边数、炮数、像素数分账；多束体积近似面积 × 栅格。</li><li>抽点必须在曲线 MRC 之后，否则制造新颈。</li><li>出处：曲线 ILT 与多束数据路径的公开可制造性讨论；OASIS 重复记录的能力边界。</li></ul>',5))])}const D=o(E,[["render",c]]);export{f as __pageData,D as default};
